#!/usr/bin/env python3
"""Pooled Fisher exact test: obs_only CRM (eps=0.2) vs argmin (K=10)."""

import json
import glob
import os
from scipy.stats import fisher_exact
from collections import defaultdict

# Known data (fallback if JSON files not found)
KNOWN_DATA = {
    "obs_only": {
        42: (44, 200),
        43: (32, 200),
        44: (32, 200),
    },
    "argmin": {
        42: (24, 200),
        43: (34, 200),
        44: (26, 200),
    },
}

DATA_DIR = "/root/autodl-tmp/libero_data"

def load_from_json(method, seed):
    """Try to load results from JSON files."""
    if method == "obs_only":
        pattern = f"{DATA_DIR}/crm_eval_obs_only_*_seed{seed}*.json"
    else:
        pattern = f"{DATA_DIR}/crm_eval_argmin_*_seed{seed}*.json"

    files = glob.glob(pattern)
    if not files:
        # Try alternative patterns
        if method == "obs_only":
            pattern = f"{DATA_DIR}/crm_eval_*obs_only*seed{seed}*.json"
        else:
            pattern = f"{DATA_DIR}/crm_eval_*argmin*seed{seed}*.json"
        files = glob.glob(pattern)

    if not files:
        return None

    total_success = 0
    total_trials = 0
    for f in files:
        try:
            with open(f) as fp:
                data = json.load(fp)
            if isinstance(data, dict):
                if "success" in data and "total" in data:
                    total_success += data["success"]
                    total_trials += data["total"]
                elif "results" in data:
                    for task_result in data["results"].values() if isinstance(data["results"], dict) else data["results"]:
                        if isinstance(task_result, dict):
                            total_success += sum(1 for r in task_result.get("rollouts", []) if r.get("success", False))
                            total_trials += len(task_result.get("rollouts", []))
                elif "tasks" in data:
                    for task in data["tasks"].values() if isinstance(data["tasks"], dict) else data["tasks"]:
                        if isinstance(task, dict):
                            total_success += task.get("successes", 0)
                            total_trials += task.get("total", 0)
        except (json.JSONDecodeError, KeyError):
            continue

    if total_trials > 0:
        return (total_success, total_trials)
    return None


def get_data(seeds=None):
    """Get data for all available seeds, using JSON if possible, fallback to known."""
    if seeds is None:
        seeds = [42, 43, 44, 45]

    results = {"obs_only": {}, "argmin": {}}

    for seed in seeds:
        for method in ["obs_only", "argmin"]:
            json_data = load_from_json(method, seed)
            if json_data:
                results[method][seed] = json_data
            elif seed in KNOWN_DATA.get(method, {}):
                results[method][seed] = KNOWN_DATA[method][seed]

    # Only keep seeds where both methods have data
    valid_seeds = sorted(set(results["obs_only"].keys()) & set(results["argmin"].keys()))
    return {m: {s: results[m][s] for s in valid_seeds} for m in results}, valid_seeds


def pooled_fisher_test(obs_data, argmin_data):
    """One-sided Fisher exact test: obs_only SR > argmin SR."""
    obs_success = sum(s for s, _ in obs_data.values())
    obs_total = sum(t for _, t in obs_data.values())
    arg_success = sum(s for s, _ in argmin_data.values())
    arg_total = sum(t for _, t in argmin_data.values())

    # 2x2 table: [[obs_success, obs_fail], [arg_success, arg_fail]]
    table = [
        [obs_success, obs_total - obs_success],
        [arg_success, arg_total - arg_success],
    ]
    odds_ratio, p_two = fisher_exact(table)
    # One-sided: obs_only > argmin (greater)
    _, p_greater = fisher_exact(table, alternative='greater')

    return obs_success, obs_total, arg_success, arg_total, odds_ratio, p_two, p_greater


def main():
    import sys

    # Allow specifying seeds on command line
    if len(sys.argv) > 1:
        seeds = [int(s) for s in sys.argv[1:]]
    else:
        seeds = None

    data, valid_seeds = get_data(seeds)

    if not valid_seeds:
        print("ERROR: No valid seed data found.")
        sys.exit(1)

    print("=" * 65)
    print(f"  Pooled Fisher Exact Test: obs_only (ε=0.2) vs argmin (K=10)")
    print(f"  Seeds: {valid_seeds} ({len(valid_seeds)}-seed pooled)")
    print("=" * 65)

    # Per-seed breakdown
    print(f"\n{'Seed':<8}{'obs_only SR':<18}{'argmin SR':<18}{'Δ':<10}")
    print("-" * 54)
    for seed in valid_seeds:
        os, ot = data["obs_only"][seed]
        as_, at = data["argmin"][seed]
        o_sr = os / ot * 100
        a_sr = as_ / at * 100
        print(f"{seed:<8}{os}/{ot} = {o_sr:.1f}%{'':<4}{as_}/{at} = {a_sr:.1f}%{'':<4}{o_sr - a_sr:+.1f}%")

    # Pooled results
    obs_s, obs_t, arg_s, arg_t, odds, p2, p1 = pooled_fisher_test(
        data["obs_only"], data["argmin"]
    )
    obs_sr = obs_s / obs_t * 100
    arg_sr = arg_s / arg_t * 100

    print("-" * 54)
    print(f"{'POOLED':<8}{obs_s}/{obs_t} = {obs_sr:.1f}%{'':<4}{arg_s}/{arg_t} = {arg_sr:.1f}%{'':<4}{obs_sr - arg_sr:+.1f}%")

    print(f"\n{'─' * 45}")
    print(f"  Fisher exact test (one-sided: obs > argmin)")
    print(f"  Odds ratio: {odds:.4f}")
    print(f"  p (two-sided): {p2:.6f}")
    print(f"  p (one-sided): {p1:.6f}")
    print(f"{'─' * 45}")

    # Decision
    print(f"\n  ** DECISION **")
    if p1 < 0.05:
        print(f"  p = {p1:.4f} < 0.05 → SIGNIFICANT")
        print(f"  → Narrative A: CRM obs_only significantly outperforms argmin baseline")
    else:
        print(f"  p = {p1:.4f} ≥ 0.05 → NOT SIGNIFICANT")
        print(f"  → Narrative B: No statistically significant difference (trend only)")
        if p1 < 0.10:
            print(f"     (marginally significant at α=0.10)")
    print()


if __name__ == "__main__":
    main()
